UPDATE `email_templates_default_data` SET `subject` = 'Objet Ã  évaluer : objet envoyé', `body` = 'Chèr(e) {$authorName}:<br />\\\\n<br />\\\\nCe courriel confirme que je vous ai envoyé par la poste une copie de {$objectForReviewTitle} Ã  l''adresse suivante de votre profil :<br />\\\\n{$authorMailingAddress}<br />\\\\n<br />\\\\nPour soumettre votre évaluation, veuillez vous connecter au site web de la revue et compléter le processus de soumission en ligne.<br />\\\\n<br />\\\\nURL de soumission : <a href="{$submissionUrl}">{$submissionUrl}</a><br />\\\\n<br />\\\\nN''hésitez pas Ã  me contacter si vous avez des questions ou des préoccupations Ã  propos de cette évaluation.<br />\\\\n<br />\\\\n{$editorialContactSignature}' WHERE `email_key` = 'OFR_OBJECT_MAILED' AND `locale` = 'fr_CA';
