UPDATE `email_templates_default_data` SET `subject` = 'Objet Ã  évaluer: rappel de la date d''échéance', `body` = 'Chèr(e) {$authorName}:<br />\\\\n<br />\\\\nCeci est un petit rappel que l''objet pour évaluation de {$objectForReviewTitle} est du pour le {$objectForReviewDueDate}.<br />\\\\n<br />\\\\nPour soumettre votre évaluation de l''objet, veuillez vous connecter au site web de la revue et compléter le processus de soumission d''article en ligne. Afin de vous aider, un lien pour soumettre votre article est fourni ci-dessous :<br />\\\\n<br />\\\\nURL de la soumission: <a href="{$submissionUrl}">{$submissionUrl}</a><br />\\\\n<br />\\\\nN''hésitez pas Ã  me contacter si vous avez des questions ou des inquiétudes Ã  propos de cette évaluation.<br />\\\\n<br />\\\\nMerci pour votre contribution,<br />\\\\nJ''attends avec impatience votre soumission<br />\\\\n<br />\\\\n{$editorialContactSignature}' WHERE `email_key` = 'OFR_REVIEW_REMINDER' AND `locale` = 'fr_CA';
UPDATE `email_templates_default_data` SET `body` = 'Madame, Monsieur, {$authorName}:<br />\\\\n<br />\\\\nNous nous permettons de vous rappeler que la date d''échéance du compte rendu de l''objet {$objectForReviewTitle} est le {$objectForReviewDueDate}.<br />\\\\n<br />\\\\nVeuillez vous connecter au site web de la revue et compléter le processus de soumission en ligne pour soumettre votre compte rendu. Pour faciliter votre accès au site web, l''URL de la soumission vous est fourni ci-dessous.<br />\\\\n<br />\\\\nURL de soumission : <a href="{$submissionUrl}">{$submissionUrl}</a><br />\\\\n<br />\\\\nN''hésitez pas Ã  me contacter si vous avez des questions ou besoin d''informations complémentaires concernant ce compte rendu.<br />\\\\n<br />\\\\nNous vous remercions de votre contribution Ã  la revue et nous réjouissons de recevoir votre prochaine soumission.<br />\\\\n<br />\\\\n{$editorialContactSignature}' WHERE `email_key` = 'OFR_REVIEW_REMINDER' AND `locale` = 'fr_FR';
UPDATE `email_templates_default_data` SET `subject` = 'Objet Ã  évaluer: Ã‰valuation arrivée Ã  échéance', `body` = 'Chèr(e) {$authorName}:<br />\\\\n<br />\\\\nCeci est un petit rappel que l''objet pour évaluation de {$objectForReviewTitle} était du pour le {$objectForReviewDueDate}, mais nous ne l''avons pas encore reçu.<br />\\\\n<br />\\\\nPour soumettre votre évaluation de l''objet, veuillez vous connecter au site web de la revue et compléter le processus de soumission d''article en ligne. Afin de vous aider, un lien pour soumettre votre article est fourni ci-dessous :<br />\\\\n<br />\\\\nURL de la soumission: <a href="{$submissionUrl}">{$submissionUrl}</a><br />\\\\n<br />\\\\nN''hésitez pas Ã  me contacter si vous avez des questions ou des inquiétudes Ã  propos de cette évaluation.<br />\\\\n<br />\\\\nMerci pour votre contribution,<br />\\\\nJ''attends avec impatience votre soumission<br />\\\\n<br />\\\\n{$editorialContactSignature}' WHERE `email_key` = 'OFR_REVIEW_REMINDER_LATE' AND `locale` = 'fr_CA';
