UPDATE `email_templates_default_data` SET `body` = '{$reviewerName}:<br />\\\\n<br />\\\\nConsidero que el vostre perfil és adequat per revisar el manuscrit «{$submissionTitle}» tramès a la revista {$contextName}. A continuació trobareu un resum de la tramesa, i confio que acceptareu encarregar-vos d''aquesta important tasca.<br />\\\\n<br />\\\\nUs demano que inicieu la sessió a la revista abans del {$responseDueDate} per indicar-nos si accepteu o no encarregar-vos de la revisió de la tramesa i, en cas d''acceptar-la, per accedir-hi i enregistrar-ne la revisió i recomanació.<br />\\\\n<br />\\\\nLa data límit per a la revisió és el {$reviewDueDate}.<br />\\\\n<br />\\\\nEnllaç de la tramesa: {$submissionReviewUrl}<br />\\\\n<br />\\\\nGrÃ cies per tenir en compte aquesta sol·licitud.<br />\\\\n<br />\\\\n{$editorialContactSignature}<br />\\\\n<br />\\\\n<br />\\\\n<br />\\\\n«{$submissionTitle}»<br />\\\\n<br />\\\\n{$abstractTermIfEnabled}<br />\\\\n{$submissionAbstract}' WHERE `email_key` = 'REVIEW_REQUEST_REMIND_AUTO_ONECLICK' AND `locale` = 'ca_ES';
